insert into public.posts(id,tag_id,title,body,status,is_demo) values
(gen_random_uuid(),(select id from public.interest_tags where name='生活'),'给周末留一小时空白','不必把休息排成另一份任务清单。试着关掉提醒，带一本书去街角，观察光如何慢慢移过桌面。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='摄影'),'雨后街道的五种颜色','湿润的地面会把平常被忽略的招牌、树影和天空叠在一起。试着蹲低一点，用倒影重新构图。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='设计'),'一把椅子的留白','好设计不一定需要更多元素。材料的温度、坐下时的角度和可维修的结构，同样是设计语言。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='科技'),'把通知改成主动查看','技术应该替你节省注意力。为不紧急的消息设定固定查看时间，能让工作与生活都更完整。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='游戏'),'为什么小地图让人安心','在陌生世界中，一个清晰的方向标会降低探索成本。但最难忘的惊喜往往藏在地图之外。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='情感'),'认真听完一句话','回应之前停一秒，确认自己听见的是对方的意思，而不是自己准备好的答案。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='知识'),'一杯茶里的微小科学','热水让茶叶中的香气逐渐释放。水温、时间与容器形状，都会改变你感受到的层次。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='艺术'),'在美术馆看一幅画十分钟','先不看说明。留意最先吸引你的线条，再慢慢寻找画面里的重复与意外。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='生活'),'一张真正能用的清单','清单只写今天最重要的三件事。完成后留下余地，让生活有机会发生。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='摄影'),'清晨逆光的人物轮廓','逆光会隐藏细节，却把姿态留得更清楚。让背景简单，轮廓自然会说话。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='设计'),'包装拆开之后','设计的责任不在打开包装那一刻结束。减少难以分离的材料，让使用后的处理也顺畅。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='科技'),'给旧设备第二次机会','清理文件、替换电池、安装轻量软件，可能比购买新设备更能解决眼前问题。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='游戏'),'合作游戏里的好沟通','清晰报点和一句及时鼓励，比复杂战术更能让陌生队友形成默契。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='情感'),'允许关系有安静时刻','亲近不意味着时时刻刻都要交谈。共同沉默也可以是一种自在的陪伴。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='知识'),'怎样记住刚读过的内容','读完一小段后，用自己的话写下一句总结。能讲清楚，才更可能真正理解。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='艺术'),'城市墙面上的手写字','转角处的旧招牌有独特节奏。记录这些字，也是在保存一座城市的记忆。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='生活'),'厨房里的低成本仪式感','认真摆好一只碗，给普通的晚餐留一点时间。仪式感并不依赖昂贵的物品。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='摄影'),'让阴影成为主角','正午的强光常被视为麻烦，却也创造了锐利的几何线条。换个角度，阴影就是主题。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='设计'),'更容易读的说明书','一句清楚的提示、恰好的字号和正确的步骤顺序，比华丽插图更值得被认真设计。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='科技'),'个人数据的整理日','每月花十五分钟检查应用权限，删除不再使用的账号，给数字生活做一次轻量清扫。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='游戏'),'失败也有趣的关卡','好的关卡会让你知道为什么失败，并愿意马上再试一次。反馈清楚，是公平感的来源。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='情感'),'给朋友一个具体的夸奖','与其说“你真棒”，不如说出哪一个瞬间让你感到被理解。具体的话更容易被记住。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='知识'),'从一张地图开始了解城市','沿着河流、车站与老街观察城市，许多看似偶然的布局就有了可解释的原因。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='艺术'),'听一首歌的低音线','熟悉的旋律之外，低音常在悄悄推动情绪。戴上耳机，试着只追随它走一遍。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='生活'),'植物的生长记录','每周在同一个角度拍一张照片。慢慢积累的变化，能提醒我们耐心有自己的节奏。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='摄影'),'拍下家附近的同一个角落','季节、天气、路过的人都会改变画面。重复拍摄能让熟悉的地方再次变得新鲜。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='设计'),'耐用也可以很美','细节经得起反复使用，材料能够修补替换，这种美感往往比短暂的新奇更持久。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='科技'),'搜索之前先问好问题','把模糊需求写成具体问题，注明背景与限制。更好的输入通常带来更有用的结果。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='游戏'),'游戏音乐如何提示风险','速度、音色和重复会悄悄改变你的判断。下一次游玩时，留意音乐如何引导你行动。','published',true),
(gen_random_uuid(),(select id from public.interest_tags where name='艺术'),'手作留下的微小差异','每件手作物都有一点不规则。正是这些痕迹，让材料与制作者的时间被看见。','published',true);
